css:
/* ベタ2枚をずらす */
.arc{position:absolute; left:-10%; width:120%; height:280px;
  border-radius:50% / 100% 100% 0 0}
.arc.back {background:#f4b23c; top:0;     z-index:0}
.arc.front{background:#e9e335; top:120px; z-index:1}
.on-arc{position:relative; z-index:2}   /* ロゴ等を手前の弧にまたがせる */

/* ヘアライン版: 面の内側にもう1本だけ */
.wave{position:absolute; bottom:-360px; left:-50%;
  width:200%; height:420px; border-radius:50%; background:#cfe8e6}
.wave.hair{background:transparent; border-top:1px solid #fff;
  transform:translateY(6px); z-index:2}
